def transformed_string_length(s,t):
    modulo=1000000007;counts=[0]*26
    for char in s:counts[ord(char)-97]+=1
    for _ in range(t):
        z=counts[25];counts=[z,(counts[0]+z)%modulo]+counts[1:25]
    return sum(counts)%modulo

